if src == dst:
    raise SystemExit("refusing to write the source model; dst must be a copy")
import shutil
shutil.copy2(src, dst)
doc = App.openDocument(dst)
applied = []
resized = []
created = []
missing = []
for row in moves:
    x, y, z = row["origin_mm"]
    issued = row.get("issued_size_mm")
    for i, name in enumerate(row["freecad_names"]):
        obj = doc.getObject(name)
        if obj is None:
            missing.append(name)
            continue
        if issued and i == 0:
            obj.Shape = Part.makeBox(*issued)
            resized.append(name)
            obj.Placement = App.Placement(App.Vector(x, y, z), App.Rotation())
        else:
            # Seed origins are bounding-box origins. A Feature whose shape is not
            # built from its local origin (e.g. a centred cylinder) is moved by the
            # bounding-box offset, so its bounding box lands on the seed origin.
            bb = obj.Shape.BoundBox
            obj.Placement = App.Placement(obj.Placement.Base + App.Vector(x - bb.XMin, y - bb.YMin, z - bb.ZMin),
                                          obj.Placement.Rotation)
        applied.append(name)
if creates:
    grp = doc.getObject("ISSUED_ENVELOPES") or doc.addObject("App::DocumentObjectGroup", "ISSUED_ENVELOPES")
    for row in creates:
        name = row["feature_name"]
        if doc.getObject(name) is not None:
            missing.append("exists:" + name)
            continue
        x, y, z = row["origin_mm"]
        obj = doc.addObject("Part::Feature", name)
        obj.Shape = Part.makeBox(*row["size_mm"])
        obj.Placement = App.Placement(App.Vector(x, y, z), App.Rotation())
        grp.addObject(obj)
        created.append(name)
doc.recompute()
doc.save()
App.closeDocument(doc.Name)
print(json.dumps({"applied": applied, "resized": resized, "created": created, "missing": missing}))
